import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1787003086000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Sixteen tools: eight read, eight write. With <code>FRESHRSS_READ_ONLY=true</code> only the read tools are registered.</p><p>Tools marked <strong>two-step</strong> return a single-use confirmation token on the first call and perform the operation only when called again with that token — see <a href="/guide/security#confirmation-tokens">Security</a>.</p><h2 id="stream-selectors" tabindex="-1">Stream selectors <a class="header-anchor" href="#stream-selectors" aria-label="Permalink to “Stream selectors”">​</a></h2><p>Six tools address &quot;where to read from&quot; with the same four mutually exclusive parameters. Set exactly one; the default is the whole reading list.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>feed_id</code></td><td>integer</td><td>Numeric <code>feedId</code> from <code>list_feeds</code></td></tr><tr><td><code>category</code></td><td>string</td><td>Category (folder) name, exactly as in <code>list_categories</code></td></tr><tr><td><code>label</code></td><td>string</td><td>User label name, exactly as in <code>list_categories</code></td></tr><tr><td><code>stream</code></td><td>enum</td><td><code>reading-list</code> (default), <code>starred</code>, <code>main</code>, <code>important</code></td></tr></tbody></table><p><code>main</code> and <code>important</code> are FreshRSS extensions: feeds shown on the main stream, and feeds marked as important.</p><div class="warning custom-block"><p class="custom-block-title">A wrong name looks like &quot;nothing new&quot;</p><p>Names are matched literally, including case — copy them from <code>list_categories</code>. A category, label or feed id that does <strong>not exist</strong> returns an empty list rather than an error (verified against FreshRSS 1.29.1); only a malformed built-in stream id produces HTTP 400. The listing tools add a <code>hint</code> field when they return nothing for one of these selectors, precisely so a typo is not reported as an empty inbox.</p><p>Categories and user labels also share one namespace in this API, so <code>category</code> and <code>label</code> resolve identically — the two parameters exist only so tool descriptions can stay readable.</p></div><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="get-user-info" tabindex="-1">get_user_info <a class="header-anchor" href="#get-user-info" aria-label="Permalink to “get_user_info”">​</a></h3><p>No parameters. Returns <code>userId</code>, <code>userName</code> and <code>userEmail</code>. The cheapest way to check that the credentials work.</p><h3 id="list-feeds" tabindex="-1">list_feeds <a class="header-anchor" href="#list-feeds" aria-label="Permalink to “list_feeds”">​</a></h3><p>No parameters. Every subscribed feed with <code>feedId</code>, <code>title</code>, <code>category</code>, <code>feedUrl</code>, <code>siteUrl</code>, <code>priority</code> and <code>unreadCount</code>, plus <code>feedCount</code> and <code>totalUnread</code>.</p><p>Feed URLs have any embedded credentials redacted. If <code>/unread-count</code> is unavailable the feed list is still returned, with a note and no <code>unreadCount</code>.</p><h3 id="list-categories" tabindex="-1">list_categories <a class="header-anchor" href="#list-categories" aria-label="Permalink to “list_categories”">​</a></h3><p>No parameters. Returns <code>categories</code> and <code>labels</code> separately — FreshRSS distinguishes them by the tag type even though they share a namespace — each with an <code>unreadCount</code>, plus the names of the built-in streams.</p><h3 id="get-unread-counts" tabindex="-1">get_unread_counts <a class="header-anchor" href="#get-unread-counts" aria-label="Permalink to “get_unread_counts”">​</a></h3><p>No parameters. Unread totals per feed and per category, sorted by count, with <code>totalUnread</code>. Only entries that actually have unread articles are listed.</p><h3 id="list-articles" tabindex="-1">list_articles <a class="header-anchor" href="#list-articles" aria-label="Permalink to “list_articles”">​</a></h3><p>Stream selector, plus:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>filter</code></td><td>enum</td><td><code>unread</code></td><td><code>unread</code>, <code>read</code>, <code>starred</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>1–100</td><td>20</td><td>Maximum articles</td></tr><tr><td><code>order</code></td><td>enum</td><td><code>newest</code></td><td><code>newest</code> or <code>oldest</code> by publication date</td></tr><tr><td><code>since</code></td><td>ISO date</td><td>—</td><td>Only articles published after this</td></tr><tr><td><code>until</code></td><td>ISO date</td><td>—</td><td>Only articles published before this</td></tr><tr><td><code>continuation</code></td><td>string</td><td>—</td><td>Value from a previous call, for the next page</td></tr><tr><td><code>include_content</code></td><td>boolean</td><td><code>false</code></td><td>Full article text instead of an excerpt</td></tr><tr><td><code>max_content_chars</code></td><td>100–20000</td><td>2000</td><td>Characters of text per article</td></tr></tbody></table><p>Each article carries <code>id</code>, <code>title</code>, <code>author</code>, <code>published</code>, <code>url</code>, <code>feed</code>, <code>read</code>, <code>starred</code>, <code>priority</code>, <code>labels</code>, any <code>enclosures</code>, and either <code>excerpt</code> (300 characters) or <code>content</code>. <code>since</code>/<code>until</code> also accept a bare unix timestamp.</p><p><strong>There is no keyword search</strong> — FreshRSS does not offer one over this API. Narrow with the selector and the date range, then filter what comes back.</p><h3 id="get-articles" tabindex="-1">get_articles <a class="header-anchor" href="#get-articles" aria-label="Permalink to “get_articles”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>article_ids</code></td><td>string[] (1–20)</td><td>—</td><td>Ids from <code>list_articles</code></td></tr><tr><td><code>max_content_chars</code></td><td>100–20000</td><td>2000</td><td>Characters of text per article</td></tr></tbody></table><p>Full text for specific articles. Ids that returned nothing are reported as a count — FreshRSS retention settings may have purged them.</p><h3 id="list-article-ids" tabindex="-1">list_article_ids <a class="header-anchor" href="#list-article-ids" aria-label="Permalink to “list_article_ids”">​</a></h3><p>Same parameters as <code>list_articles</code> minus the content options. Returns just <code>articleIds</code>, <code>count</code> and <code>continuation</code> — the cheap way to collect a set for <code>mark_articles</code>.</p><h3 id="export-opml" tabindex="-1">export_opml <a class="header-anchor" href="#export-opml" aria-label="Permalink to “export_opml”">​</a></h3><p>No parameters. All subscriptions as an OPML document, the portable backup format. Credentials in <code>xmlUrl</code> attributes are redacted; the document is truncated at 200 000 characters. For a readable overview use <code>list_feeds</code>.</p><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="mark-articles" tabindex="-1">mark_articles <a class="header-anchor" href="#mark-articles" aria-label="Permalink to “mark_articles”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>article_ids</code></td><td>string[] (1–100)</td><td>Ids from <code>list_articles</code></td></tr><tr><td><code>read</code></td><td>boolean</td><td><code>true</code> marks read, <code>false</code> unread</td></tr><tr><td><code>starred</code></td><td>boolean</td><td><code>true</code> adds the star, <code>false</code> removes it</td></tr><tr><td><code>add_labels</code></td><td>string[]</td><td>Labels to attach; unknown ones are created</td></tr><tr><td><code>remove_labels</code></td><td>string[]</td><td>Labels to detach</td></tr></tbody></table><p>At least one change is required; each is applied to every given article. Not confirmation-gated — see <a href="/guide/security#confirmation-tokens">why</a>.</p><h3 id="mark-all-as-read-—-two-step" tabindex="-1">mark_all_as_read — two-step <a class="header-anchor" href="#mark-all-as-read-—-two-step" aria-label="Permalink to “mark_all_as_read — two-step”">​</a></h3><p>Stream selector, plus <code>older_than</code> (ISO date, default: all) and <code>confirm_token</code>.</p><p>Marks an entire feed, category, label or stream as read. Which articles were unread before cannot be recovered, which is why it is gated.</p><h3 id="subscribe-feed" tabindex="-1">subscribe_feed <a class="header-anchor" href="#subscribe-feed" aria-label="Permalink to “subscribe_feed”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>url</code></td><td>string</td><td>Feed URL or website URL (http/https)</td></tr><tr><td><code>title</code></td><td>string</td><td>Title to use instead of the feed&#39;s own</td></tr><tr><td><code>category</code></td><td>string</td><td>Category to file it under; created if unknown</td></tr></tbody></table><p>FreshRSS discovers the feed from a website URL and then downloads it, so this can take a while — the timeout is 120 s. Loopback and link-local URLs are refused: FreshRSS fetches the URL itself, which would make this an <a href="/guide/security#subscribe-feed-is-a-server-side-fetch">SSRF primitive</a>.</p><h3 id="update-feed" tabindex="-1">update_feed <a class="header-anchor" href="#update-feed" aria-label="Permalink to “update_feed”">​</a></h3><p><code>feed_id</code> (integer, required), plus <code>title</code> and/or <code>category</code>. At least one of the two. Fields not given stay unchanged; an unknown category is created.</p><h3 id="unsubscribe-feed-—-two-step" tabindex="-1">unsubscribe_feed — two-step <a class="header-anchor" href="#unsubscribe-feed-—-two-step" aria-label="Permalink to “unsubscribe_feed — two-step”">​</a></h3><p><code>feed_id</code> (integer) and <code>confirm_token</code>.</p><p>Deletes the feed <strong>and all of its stored articles, read state and stars</strong>. Not reversible: re-subscribing starts from whatever the feed currently offers.</p><h3 id="rename-category-or-label" tabindex="-1">rename_category_or_label <a class="header-anchor" href="#rename-category-or-label" aria-label="Permalink to “rename_category_or_label”">​</a></h3><p><code>name</code> and <code>new_name</code>. FreshRSS resolves the name against categories first and falls back to labels, so one tool covers both. Feeds and articles keep their assignment.</p><h3 id="delete-category-or-label-—-two-step" tabindex="-1">delete_category_or_label — two-step <a class="header-anchor" href="#delete-category-or-label-—-two-step" aria-label="Permalink to “delete_category_or_label — two-step”">​</a></h3><p><code>name</code> and <code>confirm_token</code>.</p><p>For a <strong>category</strong>, its feeds move to the default category and no articles are lost. For a <strong>label</strong>, it is detached from every article. Because FreshRSS matches categories first, a category and a label of the same name cannot be told apart here.</p><h3 id="import-opml-—-two-step" tabindex="-1">import_opml — two-step <a class="header-anchor" href="#import-opml-—-two-step" aria-label="Permalink to “import_opml — two-step”">​</a></h3><p><code>opml</code> (the document, up to 900 000 characters) and <code>confirm_token</code>.</p><p>Subscribes to every feed in the document, creates the categories it names, then refreshes everything — minutes, on a large file. There is no bulk undo. Documents with a <code>&lt;!DOCTYPE&gt;</code> or <code>&lt;!ENTITY&gt;</code> declaration are <a href="/guide/security#import-opml-refuses-a-doctype">refused</a>.</p><p>The token is bound to a fingerprint of the exact document, so confirming one OPML cannot authorise importing another.</p>`,54)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};